$(function(){$("#contact-form, #footer-quote-form, form[action='/assets/mail.php']").submit(function(e){e.preventDefault();var form=$(this);var formMessages=form.find(".ajax-response");if(!formMessages.length){formMessages=form.closest(".contact__form-wrap, .footer-reference-form-panel").find(".ajax-response").first()}var formData=form.serialize();$.ajax({type:"POST",url:form.attr("action"),data:formData}).done(function(response){formMessages.removeClass("error");formMessages.addClass("success");formMessages.text(response);form.find("input:not([type='hidden']), textarea").val("");form.find("select").prop("selectedIndex",0)}).fail(function(data){formMessages.removeClass("success");formMessages.addClass("error");if(data.responseText!==""){formMessages.text(data.responseText)}else{formMessages.text("Oops! An error occured and your message could not be sent.")}})})});